<?php

namespace App\Support;

/**
 * Renders the shell scripts an external load generator runs. Both are
 * generated by the target server — the bootstrap from the pairing session,
 * the work fragment from HttpBenchCommand::plan() at the moment the run's
 * HTTP stage arms — so the load a second machine drives is exactly the
 * standard load a self-test would run, by construction.
 */
class GeneratorScript
{
    /**
     * The script behind `curl … | sh`: preflights oha and reachability,
     * measures the round trip, handshakes, then polls for work.
     *
     * @param  array<string, mixed>  $session
     */
    public function bootstrap(array $session): string
    {
        return view('bench.generator-script', [
            'base' => escapeshellarg($session['base_url']),
            'target' => escapeshellarg($session['target_url']),
            'token' => escapeshellarg($session['token']),
            'curlInsecure' => $this->curlInsecure($session),
        ])->render();
    }

    /**
     * The per-route work fragment the bootstrap fetches once the stage arms:
     * warmup, measured window, upload — same flags, order, and warmup as the
     * local chain, because both render from the same plan.
     *
     * @param  array<int, array<string, mixed>>  $plan
     * @param  array<string, mixed>  $session
     */
    public function work(array $plan, array $session): string
    {
        return view('bench.generator-work', [
            'base' => escapeshellarg($session['base_url']),
            'token' => escapeshellarg($session['token']),
            'curlInsecure' => $this->curlInsecure($session),
            'routes' => array_map(fn (array $route): array => [
                ...$route,
                // The upload URL segment matches the file name convention
                // (db_read → db-read), not the internal key.
                'upload_key' => str_replace('_', '-', $route['key']),
                'banner_quoted' => escapeshellarg($route['banner']),
                'path_quoted' => escapeshellarg($route['path']),
                'url_quoted' => escapeshellarg($route['url']),
            ], $plan),
        ])->render();
    }

    /**
     * -k whenever either side of the conversation is https: the target is
     * often a self-signed loopback certificate, and the token — not the
     * transport — is what authenticates this exchange.
     *
     * @param  array<string, mixed>  $session
     */
    protected function curlInsecure(array $session): string
    {
        $https = str_starts_with($session['base_url'] ?? '', 'https://')
            || str_starts_with($session['target_url'] ?? '', 'https://');

        return $https ? '-k' : '';
    }
}
